var t=[{title:`Varför axlar varierar`,text:`Axeln har ett stort rörelseomfång och förlitar sig på mycket muskulatur för att vara stabil. Att sträcka sig över huvudet, djupa presspositioner och snabba rörelser kan kännas mycket olika från en person till en annan. En rörelse som är begränsad eller smärtsam säger dig något om vilka övningar du ska välja. Den bevisar inte att du har en särskild skada.`},{title:`Anpassa övningen`,text:`Om en skivstångspress över huvudet besvärar dig, prova en hantelpress med neutralt grepp, en stödd rodd eller en armhävning mot vägg. Ändra djup eller riktning innan du lägger till motstånd. Dragövningar är ett bra komplement till pressar, men inget fast förhållande mellan press och drag botar axelsmärta.`},{title:`Kontroll och gradvis exponering`,text:`Medan du lär dig en rörelse, använd långsamma, kontrollerade repetitioner, ett bekvämt omfång och lätta vikter. Att bygga axelstyrka kan kräva gradvis tuffare arbete, men den progressionen ska inte förvärra dina symtom. Att tvinga fram en stretch genom smärta eller testa tunga lyft över huvudet om och om igen tar dig inte dit snabbare.`},{title:`Varningstecken`,text:`Sök medicinsk rådgivning snabbt vid svår smärta efter ett fall, en arm du inte kan röra, en synlig deformitet, stor svullnad eller ny domning som inte går över. Symtom som inte förbättras behöver också undersökas av en yrkesperson.`},{title:`Så använder du TrainUp`,text:`Lägg till din axel under begränsningar i Profil, med anteckningar, och håll din utrustningslista uppdaterad. Programmet väljer då bara övningar som passar dina begränsningar, din utrustning, din nivå och din koordination. Om en övning gör ont under ett pass, tryck på ”Jag känner smärta” för att avsluta den direkt. Den ligger utanför dina program tills du återupptar den från Profil. Att byta övningar på det här sättet behandlar inte impingement, rotatorkuffsjukdom eller något annat specifikt tillstånd.`}];var r=[{label:`NHS: axelsmärta och varningstecken`,url:`https://www.nhs.uk/symptoms/shoulder-pain/`},{label:`ACSM:s ställningstagande 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var a={sections:t,sources:r};export{a as default,t as sections,r as sources};